mapper.sql:
v.store_id = #{criteria.storeId}

    AND (
        v.barcode LIKE CONCAT(#{criteria.keyword}, '%')
        OR v.product_name LIKE CONCAT('%', #{criteria.keyword}, '%')
    )


    AND v.category_id = #{criteria.categoryId}


    AND EXISTS (
        SELECT 1
        FROM product_supplier ps_filter
        WHERE ps_filter.product_id = v.product_id
          AND ps_filter.supplier_id = #{criteria.supplierId}
    )


    AND v.warehouse_id = #{criteria.warehouseId}


    AND v.inventory_status = #{criteria.inventoryStatus}


    AND v.data_status = #{criteria.dataStatus}


    AND v.current_quantity >= #{criteria.minStock}


    AND v.current_quantity <= #{criteria.maxStock}

mapper.select:
SELECT ps.product_id, s.supplier_name FROM product_supplier ps INNER JOIN supplier s ON s.id = ps.supplier_id INNER JOIN store_product_inventory spi ON spi.product_id = ps.product_id AND spi.store_id = #{storeId} WHERE ps.product_id IN
#{productId}
ORDER BY ps.product_id ASC, ps.is_primary DESC, s.supplier_name ASC, s.id ASC

SELECT sales.product_id, COALESCE(SUM(sales.sales_quantity), 0) AS sales_quantity, COALESCE(SUM(sales.sales_amount), 0) AS sales_amount, COALESCE(SUM(sales.gross_profit_amount), 0) AS gross_profit_amount FROM v_posted_daily_product_sales sales WHERE sales.store_id = #{storeId} AND sales.business_date BETWEEN #{startDate} AND #{endDate} AND sales.product_id IN
#{productId}
GROUP BY sales.product_id ORDER BY sales.product_id ASC
